"""Build the two self-contained review presentations, with no external assets."""
from pathlib import Path
from html import escape

ROOT=Path(__file__).resolve().parent
CATALOG=[('OIR','Resolution','40%'),('Silence','Interaction','20%'),('Mailing Address','Documentation','20%'),('TPS','Resolution','20%'),('Notes','Documentation','10%')]

def presentation(ai=False):
    title='QA with AI coaching' if ai else 'QA with Excel and Python'
    intro='Explore the evidence, then ask AI to help prepare the coaching conversation.' if ai else 'A familiar workbook that makes scores, findings and coaching progress easier to review.'
    flow=['Excel exports','Python calculations','Local database','Dashboard + OpenAI drafts'] if ai else ['Excel exports','Python calculations','Excel workbook','Supervisor review']
    cards=[('Overview','Scores, audit counts and last-month comparison.'),('Pivot Tables','Filter by team or agent and open the evidence.'),('Markdowns','Find recurring findings by call type.'),('Agent & coaching' if ai else 'Audit Detail','Review evidence and '+('save agreed coaching.' if ai else 'find the original call.'))]
    palette='--bg:#0d1c30;--card:#15283e;--ink:#f4f7fb;--muted:#bbcbdf;--accent:#73e3c6;--line:#30445d' if ai else '--bg:#f7f4ed;--card:#ffffff;--ink:#182b42;--muted:#52667d;--accent:#126b61;--line:#d8dfdf'
    cost='''<div class="calculator"><label>Agents <input id="agents" type="number" min="1" max="5000" value="42"></label>
    <label>Model <select id="model"><option value="nano">GPT-5 nano</option><option value="luna">GPT-6 Luna</option></select></label>
    <label>Input tokens per request <input id="input" type="number" min="100" value="2000"></label>
    <label>Billable output tokens per request <input id="output" type="number" min="100" max="2000" value="800"></label></div>
    <div class="price" id="monthly">$0.11</div><p id="volume"></p>
    <p class="muted">Four coaching drafts per agent, four summaries and one hundred questions each month. Standard interactive prices; output includes reasoning. Hosting, existing licenses, labor, taxes and cache-write charges are extra.</p>
    <p>Default: GPT-5 nano, $0.05 input and $0.40 output per million tokens. It is deprecated, with its snapshot scheduled to retire December 11, 2026. The alternative is selected manually; the app never silently upgrades the model.</p>
    <p><a href="https://developers.openai.com/api/docs/models/gpt-5-nano">Nano pricing</a> · <a href="https://developers.openai.com/api/docs/models/gpt-6-luna">Luna pricing</a> · <a href="https://developers.openai.com/api/docs/deprecations">Retirement notice</a></p>''' if ai else '''<div class="price">$0</div><p>Additional AI usage cost. The limited solution does not call an AI service.</p><p class="muted">Assumes Excel, Python and a computer are already available. Existing licenses, staff time and maintenance are outside this estimate.</p>'''
    extra='''<div class="cards"><article><h3>Weekly summary</h3><p>Explain the calculated results and point to supporting audits.</p></article><article><h3>GROW coaching</h3><p>Prepare Goal, Reality, Options and Will for the selected agent.</p></article><article><h3>Ask QA</h3><p>Ask about the filtered report. The answer can only use that evidence.</p></article></div><p>AI reads existing findings. Evaluator flags, scores and status calculations remain authoritative. Names stay in local views; the OpenAI packet uses masked excerpts. Each AI response is a draft for a supervisor to review.</p><p class="muted">Local demo uses Streamlit and SQLite. A shared company pilot still needs sign-in, permissions, shared storage and backups.</p>''' if ai else '''<p>Run Update QA when new exports arrive. Excel filters help you browse the report; PivotTable filters recalculate the selected pivot. To change the Overview or coaching status, choose the new scope in Update QA.</p><p class="muted">No macros or database server. Coaching input stays in a separate file so refreshes preserve it.</p>'''
    run='''<li>Follow <a href="../PORTABLE_SETUP.md">portable setup</a> once on Windows, Mac or Linux.</li><li>Run <code>python launch.py ai</code> in the QA project folder. Windows also has START_AI.cmd.</li><li>Open the running computer's dashboard address. Phones and tablets use that address in their browser.</li><li>Enter your key in Settings, then request a draft on AI assistant.</li>''' if ai else '''<li>Follow <a href="../PORTABLE_SETUP.md">portable setup</a> once on Windows, Mac or Linux.</li><li>Run <code>python launch.py limited --demo</code> in the QA project folder. Windows also has UPDATE_QA.cmd for a filter form.</li><li>Open the generated workbook in Excel desktop. Use Pivot Tables and its yellow filter dropdowns. Double-click a number for source rows.</li>'''
    js='''function cost(){const a=Math.max(1,Number(document.querySelector('#agents').value)||1),n=a*4+104,m=document.querySelector('#model').value,p=m==='nano'?[.05,.4]:[.1,.5],i=Math.max(0,Number(document.querySelector('#input').value)||0),o=Math.max(0,Number(document.querySelector('#output').value)||0);document.querySelector('#monthly').textContent='$'+(n*(i*p[0]+o*p[1])/1000000).toFixed(2);document.querySelector('#volume').textContent=n.toLocaleString()+' requests per month. Approximate API cost in USD.';}document.querySelectorAll('input,select').forEach(e=>e.addEventListener('input',cost));cost();''' if ai else ''
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>
    :root{{{palette}}}*{{box-sizing:border-box}}html{{scroll-behavior:smooth}}body{{margin:0;background:var(--bg);color:var(--ink);font:18px/1.6 Arial,sans-serif}}a{{color:var(--accent)}}nav{{position:sticky;top:0;background:var(--bg);border-bottom:1px solid var(--line);z-index:10;display:flex;justify-content:space-between;gap:16px;padding:18px 6vw;font-size:14px}}nav div{{display:flex;gap:22px}}main{{max-width:1150px;margin:auto;padding:0 32px}}section{{padding:76px 0;border-bottom:1px solid var(--line);scroll-margin-top:60px}}h1{{font-size:clamp(42px,6vw,76px);line-height:1.05;letter-spacing:-2px;margin:16px 0 25px;max-width:900px}}h2{{font-size:36px;line-height:1.2}}h3{{font-size:20px;margin-top:0}}.label{{color:var(--accent);font-size:14px;text-transform:uppercase;letter-spacing:2px}}.lede{{font-size:23px;max-width:750px}}.muted{{color:var(--muted);font-size:15px}}.cards,.flow{{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:16px;margin:30px 0}}article,.mock,.calculator{{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:24px}}article p{{font-size:16px;color:var(--muted)}}.flow div{{border-top:3px solid var(--accent);padding:15px 0}}.flow small{{display:block;color:var(--muted)}}.mock{{margin-top:36px}}.stats{{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}}.stats strong{{font-size:36px;display:block}}.stats span{{font-size:14px;color:var(--muted)}}table{{width:100%;border-collapse:collapse;font-size:16px;margin:25px 0}}th,td{{text-align:left;padding:14px;border-bottom:1px solid var(--line)}}th{{color:var(--muted)}}.price{{font-size:72px;line-height:1.2;color:var(--accent);margin:26px 0}}.calculator{{display:grid;grid-template-columns:1fr 1fr;gap:20px}}label{{font-size:15px}}input,select{{width:100%;display:block;margin-top:8px;padding:12px;font:inherit;border-radius:6px;border:1px solid var(--line);color:var(--ink);background:var(--bg)}}.button{{display:inline-block;background:var(--accent);color:{'#0d1c30' if ai else '#fff'};padding:12px 22px;border-radius:7px;text-decoration:none;font-weight:bold}}footer{{padding:36px 0;font-size:14px;color:var(--muted)}}@media(max-width:650px){{nav{{position:static;display:block}}nav div{{flex-wrap:wrap;margin-top:10px}}main{{padding:0 22px}}section{{padding:45px 0}}.stats{{grid-template-columns:1fr}}.calculator{{grid-template-columns:1fr}}h2{{font-size:28px}}}}
    </style></head><body><nav><strong>QA tracker · {'AI proposal' if ai else 'Limited proposal'}</strong><div><a href="#findings">Findings</a><a href="#views">Views</a><a href="#cost">Cost</a><a href="#try">Try it</a></div></nav><main>
    <section><div class="label">Solution {'02' if ai else '01'} · review presentation</div><h1>{title}</h1><p class="lede">{intro}</p><a class="button" href="#views">Explore the solution</a><div class="mock"><p class="muted">Synthetic demo results · August 2026</p><div class="stats"><div><strong>89.7%</strong><span>QA month to date</span></div><div><strong>714</strong><span>Audits in the month</span></div><div><strong>4 views</strong><span>In the Excel report, including Pivot Tables</span></div></div></div></section>
    <section id="findings"><div class="label">Start with what QA already knows</div><h2>The evaluator has already identified the miss.</h2><p>The tracker brings existing findings together so supervisors can see patterns and discuss improvement. These category labels and listed impacts stay the same in both proposals.</p><table><thead><tr><th>Markdown</th><th>Category</th><th>Listed impact on the call</th></tr></thead><tbody>{''.join('<tr>'+''.join('<td>'+escape(v)+'</td>' for v in r)+'</tr>' for r in CATALOG)}</tbody></table><p class="muted">The final QA score comes from the audit export. Actual point loss comes from exported deductions; the listed impacts are not added to rebuild a score.</p></section>
    <section id="views"><div class="label">Easy navigation</div><h2>From a team result to the call behind it.</h2><div class="cards">{''.join('<article><h3>'+a+'</h3><p>'+b+'</p></article>' for a,b in cards)}</div><p>Names are preserved. Agent names appear with login IDs in pivots, so two people with the same name remain separate. Excel includes navigation links and native PivotTables.</p><div class="flow">{''.join('<div><small>Step '+str(i+1)+'</small><strong>'+s+'</strong></div>' for i,s in enumerate(flow))}</div>{extra}</section>
    <section><div class="label">Understand the evidence</div><h2>The supplied file is a call list.</h2><p>It contains 1,512 selected calls from 42 agents. It does not contain their QA scores, evaluator flags or coaching history. The sampled-call pivot keeps the original names and shows review coverage.</p><p>The review uses those agent names on simulated QA rows instead of Demo agent labels. Scores, teams and coaching are examples. Synthetic transaction IDs keep the simulation separate from actual sampled calls, which still await their audit results.</p><p class="muted">QA averages use underlying scored audits. Unknown markdown results do not count as a pass. Small samples remain labelled.</p></section>
    <section id="cost"><div class="label">Expected cost</div><h2>{'Small requests keep the AI cost low.' if ai else 'Use the tools you already have.'}</h2>{cost}</section>
    <section id="try"><div class="label">Run locally</div><h2>Ready for your review.</h2><ol>{run}</ol><p><a href="spec.md">Read the full spec</a> · <a href="output/QA_Review.xlsx">Open the Excel report</a></p><p class="muted">The local software and mock AI checks have been exercised. A live OpenAI response still needs your API key. Native Excel dropdown interaction remains a manual review step.</p></section>
    <section><div class="label">Use on another device</div><h2>One project, portable setup.</h2><p>Standard Python runs the solutions on Windows, Mac and Linux. No user-name paths or Codex installation are required. An optional Docker package provides a repeatable server setup.</p><p>The dashboard is the mobile option: phones and tablets use the browser address of an accessible running computer or server. The limited workbook's native PivotTables need compatible desktop Excel.</p><p>A fresh checkout creates anonymous example calls if the supplied file is absent. Your configured private input keeps its original names. Company sign-in and shared hosting are still a deployment step; uploading to GitHub alone does not start a shared dashboard.</p></section>
    <footer>Prepared October 5, 2026. See the spec and test results for assumptions and deployment limits.</footer></main><script>{js}</script></body></html>'''

if __name__=='__main__':
    for folder,ai in [('01-limited-tools',False),('02-modern-ai',True)]:
        (ROOT/folder/'presentation.html').write_text(presentation(ai),encoding='utf-8')
    print('Created both HTML presentations.')
